// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read drafts with the backup verifier": "in1_Readdraftswiththebackupv"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read drafts with the backup verifier";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"week_q": encodeURIComponent(out.week), "failed_body": JSON.stringify({ recipe: 'R12.2', item: 'late', reason: 'write failed', detail: 'A verification or publication write failed; check the draft and pre-read', owner: $('Config').first().json.verifier }), "preread_body": JSON.stringify(out.preread)});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 13 at 16:45: a draft still not verified is left out; step 11 runs, marked "not verified".
const drafts = ($('Read drafts with the backup verifier').first().json.items || []).filter(d => d.stage === 'backup');
return drafts.map(d => ({ json: { week: d.week, preread: { id: d.week, week: d.week, version: d.version, table: d.table, commentary: d.commentary,
  narrative: null, note: 'no narrative this week (not verified)', reason: 'not verified' } } }));
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };
